WITH exploded AS (SELECT id, plan, currency, tier_value FROM price_tiers LATERAL VIEW EXPLODE(tier_limits) x AS tier_value), scored AS (SELECT plan, tier_value, CUME_DIST() OVER w_running tier_value_cume_dist FROM exploded WINDOW w_running AS (PARTITION BY currency, plan ORDER BY tier_value DESC NULLS FIRST)), enriched AS (SELECT *, STDDEV_SAMP(tier_value_cume_dist) OVER w_hist plan_stddev_samp_tier_value_cume_dist FROM scored WHERE tier_value <= 27 WINDOW w_hist AS (PARTITION BY plan)), filtered AS (SELECT *, LENGTH(plan) plan_length FROM enriched WHERE tier_value_cume_dist <= 0.34), base AS (SELECT *, LEAST(plan_length, tier_value) least_plan_length_tier_value, plan_length * tier_value_cume_dist plan_length_times_tier_value_cume_dist FROM filtered WHERE tier_value_cume_dist > 0.33) SELECT plan, tier_value, plan_stddev_samp_tier_value_cume_dist FROM base ORDER BY plan_stddev_samp_tier_value_cume_dist DESC NULLS LAST, plan ASC;
